-- FUNC10: Financeiro/SIAFIC/Tesouraria. Aderência funcional parcial; não certifica conformidade legal integral.
create schema if not exists sigov;

-- Complementos estruturais que não alteram destrutivamente o núcleo financeiro publicado.
alter table if exists sigov.financeiro_empenho add column if not exists tipo varchar(12) not null default 'ORDINARIO';
alter table if exists sigov.financeiro_empenho add column if not exists contrato_id bigint;
alter table if exists sigov.financeiro_empenho add column if not exists compra_id bigint;
alter table if exists sigov.financeiro_empenho add column if not exists data_emissao date not null default current_date;
alter table if exists sigov.financeiro_empenho add column if not exists justificativa text;
alter table if exists sigov.financeiro_liquidacao add column if not exists documento_habil varchar(120);
alter table if exists sigov.financeiro_liquidacao add column if not exists data_liquidacao date not null default current_date;
alter table if exists sigov.financeiro_liquidacao add column if not exists atestador varchar(180);
alter table if exists sigov.financeiro_liquidacao add column if not exists valor_glosa numeric(18,2) not null default 0;
alter table if exists sigov.financeiro_liquidacao add column if not exists recebimento_almoxarifado_id bigint;
alter table if exists sigov.financeiro_liquidacao add column if not exists incorporacao_patrimonio_id bigint;
alter table if exists sigov.financeiro_liquidacao add column if not exists justificativa text;
alter table if exists sigov.financeiro_pagamento add column if not exists ordem_pagamento_id bigint;
alter table if exists sigov.financeiro_pagamento add column if not exists meio_pagamento varchar(20) not null default 'OUTRO';
alter table if exists sigov.financeiro_pagamento add column if not exists documento_bancario varchar(120);
alter table if exists sigov.financeiro_pagamento add column if not exists justificativa text;

create table if not exists sigov.financeiro_funcao (
 id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null,
 codigo varchar(10) not null, nome varchar(180) not null, ativo boolean not null default true, is_deleted boolean not null default false,
 created_at timestamptz not null default now(), updated_at timestamptz, deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint,
 unique(tenant_id,entidade_id,codigo));
create table if not exists sigov.financeiro_subfuncao (
 id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, funcao_id bigint not null references sigov.financeiro_funcao(id),
 codigo varchar(10) not null, nome varchar(180) not null, ativo boolean not null default true, is_deleted boolean not null default false,
 created_at timestamptz not null default now(), updated_at timestamptz, deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint,
 unique(tenant_id,entidade_id,codigo));
create table if not exists sigov.financeiro_credor (
 id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null,
 pessoa_id bigint, fornecedor_id bigint, nome varchar(180) not null, documento varchar(20), ativo boolean not null default true, is_deleted boolean not null default false,
 created_at timestamptz not null default now(), updated_at timestamptz, deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint);
create table if not exists sigov.financeiro_empenho_movimento (
 id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, exercicio_id bigint not null,
 empenho_id bigint not null references sigov.financeiro_empenho(id), tipo varchar(16) not null check(tipo in ('EMISSAO','REFORCO','ANULACAO')),
 valor numeric(18,2) not null check(valor>0), justificativa text, created_at timestamptz not null default now(), created_by bigint,
 check(tipo <> 'ANULACAO' or nullif(btrim(justificativa),'') is not null));
create table if not exists sigov.financeiro_ordem_pagamento (
 id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, exercicio_id bigint not null,
 liquidacao_id bigint not null references sigov.financeiro_liquidacao(id), conta_bancaria_id bigint, numero varchar(60) not null, favorecido varchar(180) not null,
 valor numeric(18,2) not null check(valor>0), vencimento date not null, status varchar(16) not null default 'EMITIDA' check(status in ('EMITIDA','AUTORIZADA','PAGA','CANCELADA')),
 autorizado_por bigint, autorizado_em timestamptz, justificativa text, ativo boolean not null default true, is_deleted boolean not null default false,
 created_at timestamptz not null default now(), updated_at timestamptz, deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint,
 unique(tenant_id,entidade_id,exercicio_id,numero), check(status <> 'CANCELADA' or nullif(btrim(justificativa),'') is not null));
create table if not exists sigov.financeiro_conciliacao_bancaria (
 id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, exercicio_id bigint not null,
 conta_bancaria_id bigint not null, data_extrato date not null, saldo_extrato numeric(18,2) not null, saldo_sistema numeric(18,2) not null,
 diferenca numeric(18,2) generated always as (saldo_extrato-saldo_sistema) stored, observacao text, status varchar(16) not null default 'PENDENTE' check(status in ('PENDENTE','CONCILIADA','CANCELADA')),
 justificativa text, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz,
 deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint, check(status <> 'CANCELADA' or nullif(btrim(justificativa),'') is not null));
create table if not exists sigov.financeiro_receita_classificacao (
 id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, codigo varchar(30) not null, nome varchar(180) not null,
 ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz, deleted_at timestamptz,
 created_by bigint, updated_by bigint, deleted_by bigint, unique(tenant_id,entidade_id,codigo));
create table if not exists sigov.financeiro_receita_prevista (
 id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, exercicio_id bigint not null,
 classificacao_id bigint not null references sigov.financeiro_receita_classificacao(id), valor_previsto numeric(18,2) not null check(valor_previsto>=0), valor_lancado numeric(18,2) not null default 0 check(valor_lancado>=0),
 ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz, deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint);
create table if not exists sigov.financeiro_receita_arrecadada (
 id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, exercicio_id bigint not null,
 receita_prevista_id bigint references sigov.financeiro_receita_prevista(id), origem varchar(16) not null check(origem in ('TRIBUTARIO','SANEAMENTO','MANUAL')),
 origem_id bigint, data_arrecadacao date not null, valor numeric(18,2) not null check(valor>0), documento varchar(120),
 ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz, deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint);
create unique index if not exists ux_fin_receita_origem on sigov.financeiro_receita_arrecadada(tenant_id,entidade_id,origem,origem_id) where origem_id is not null and is_deleted=false;
create table if not exists sigov.financeiro_resto_pagar (
 id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, exercicio_id bigint not null, exercicio_origem integer not null,
 empenho_id bigint not null references sigov.financeiro_empenho(id), liquidacao_id bigint references sigov.financeiro_liquidacao(id), tipo varchar(20) not null check(tipo in ('PROCESSADO','NAO_PROCESSADO')),
 valor_inscrito numeric(18,2) not null check(valor_inscrito>0), valor_pago numeric(18,2) not null default 0 check(valor_pago>=0 and valor_pago<=valor_inscrito),
 status varchar(16) not null default 'INSCRITO' check(status in ('INSCRITO','PAGO_PARCIAL','PAGO','CANCELADO')), justificativa text,
 ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz, deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint,
 check((tipo='PROCESSADO' and liquidacao_id is not null) or tipo='NAO_PROCESSADO'), check(status <> 'CANCELADO' or nullif(btrim(justificativa),'') is not null));
create table if not exists sigov.financeiro_suprimento (
 id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, exercicio_id bigint not null, servidor_id bigint not null,
 finalidade text not null, valor numeric(18,2) not null check(valor>0), prazo_prestacao date not null, status varchar(20) not null default 'CONCEDIDO' check(status in ('CONCEDIDO','PRESTADO','APROVADO','REJEITADO','ENCERRADO')),
 valor_devolvido numeric(18,2) not null default 0 check(valor_devolvido>=0 and valor_devolvido<=valor), justificativa text,
 ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz, deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint);
create table if not exists sigov.financeiro_suprimento_prestacao (
 id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, suprimento_id bigint not null references sigov.financeiro_suprimento(id),
 data_prestacao date not null, valor_comprovado numeric(18,2) not null check(valor_comprovado>=0), observacao text, status varchar(16) not null default 'PENDENTE' check(status in ('PENDENTE','APROVADA','REJEITADA')),
 justificativa text, created_at timestamptz not null default now(), updated_at timestamptz, created_by bigint, updated_by bigint, check(status <> 'REJEITADA' or nullif(btrim(justificativa),'') is not null));
create table if not exists sigov.financeiro_auditoria (
 id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, usuario_id bigint, acao varchar(80) not null,
 recurso varchar(100) not null, recurso_id bigint, dados_anteriores jsonb, dados_novos jsonb, correlation_id varchar(100), ip inet, created_at timestamptz not null default now());

-- Regras concorrentes: serializam a dotação/empenho/liquidação antes das somas.
create or replace function sigov.func10_validar_fluxo() returns trigger language plpgsql as $$
declare limite numeric; utilizado numeric;
begin
 if tg_table_name='financeiro_empenho' then
  select valor_atualizado into limite from sigov.financeiro_dotacao where id=new.dotacao_id for update;
  select coalesce(sum(valor),0) into utilizado from sigov.financeiro_empenho where dotacao_id=new.dotacao_id and id<>coalesce(new.id,0) and status<>'ANULADO' and not is_deleted;
  if utilizado+new.valor>limite then raise exception 'Saldo orçamentário insuficiente'; end if;
 elsif tg_table_name='financeiro_liquidacao' then
  select valor into limite from sigov.financeiro_empenho where id=new.empenho_id for update;
  select coalesce(sum(valor-valor_glosa),0) into utilizado from sigov.financeiro_liquidacao where empenho_id=new.empenho_id and id<>coalesce(new.id,0) and status<>'CANCELADA' and not is_deleted;
  if utilizado+new.valor-new.valor_glosa>limite then raise exception 'Liquidação excede saldo empenhado'; end if;
 elsif tg_table_name='financeiro_ordem_pagamento' then
  select valor-valor_glosa into limite from sigov.financeiro_liquidacao where id=new.liquidacao_id for update;
  select coalesce(sum(valor),0) into utilizado from sigov.financeiro_ordem_pagamento where liquidacao_id=new.liquidacao_id and id<>coalesce(new.id,0) and status<>'CANCELADA' and not is_deleted;
  if utilizado+new.valor>limite then raise exception 'Ordem excede saldo liquidado'; end if;
 elsif tg_table_name='financeiro_pagamento' and new.ordem_pagamento_id is not null then
  select valor into limite from sigov.financeiro_ordem_pagamento where id=new.ordem_pagamento_id and status='AUTORIZADA' for update;
  if limite is null then raise exception 'Ordem de pagamento não autorizada'; end if;
  select coalesce(sum(valor),0) into utilizado from sigov.financeiro_pagamento where ordem_pagamento_id=new.ordem_pagamento_id and id<>coalesce(new.id,0) and status<>'CANCELADO' and not is_deleted;
  if utilizado+new.valor>limite then raise exception 'Pagamento excede saldo autorizado'; end if;
 end if; return new;
end $$;
drop trigger if exists trg_func10_empenho on sigov.financeiro_empenho; create trigger trg_func10_empenho before insert or update of valor,dotacao_id,status on sigov.financeiro_empenho for each row execute function sigov.func10_validar_fluxo();
drop trigger if exists trg_func10_liquidacao on sigov.financeiro_liquidacao; create trigger trg_func10_liquidacao before insert or update of valor,valor_glosa,empenho_id,status on sigov.financeiro_liquidacao for each row execute function sigov.func10_validar_fluxo();
drop trigger if exists trg_func10_ordem on sigov.financeiro_ordem_pagamento; create trigger trg_func10_ordem before insert or update of valor,liquidacao_id,status on sigov.financeiro_ordem_pagamento for each row execute function sigov.func10_validar_fluxo();
drop trigger if exists trg_func10_pagamento on sigov.financeiro_pagamento; create trigger trg_func10_pagamento before insert or update of valor,ordem_pagamento_id,status on sigov.financeiro_pagamento for each row execute function sigov.func10_validar_fluxo();

create index if not exists ix_fin10_dotacao_escopo on sigov.financeiro_dotacao(tenant_id,entidade_id,exercicio_id,status);
create index if not exists ix_fin10_empenho_credor on sigov.financeiro_empenho(tenant_id,entidade_id,exercicio_id,credor_id,status,data_emissao);
create index if not exists ix_fin10_liquidacao_data on sigov.financeiro_liquidacao(tenant_id,entidade_id,exercicio_id,empenho_id,status,data_liquidacao);
create index if not exists ix_fin10_ordem_vencimento on sigov.financeiro_ordem_pagamento(tenant_id,entidade_id,exercicio_id,status,vencimento);
create index if not exists ix_fin10_pagamento_data on sigov.financeiro_pagamento(tenant_id,entidade_id,exercicio_id,conta_bancaria_id,status,data_pagamento);
create index if not exists ix_fin10_conciliacao on sigov.financeiro_conciliacao_bancaria(tenant_id,entidade_id,exercicio_id,conta_bancaria_id,status,data_extrato);
create index if not exists ix_fin10_receita_data on sigov.financeiro_receita_arrecadada(tenant_id,entidade_id,exercicio_id,origem,data_arrecadacao);
create index if not exists ix_fin10_resto_status on sigov.financeiro_resto_pagar(tenant_id,entidade_id,exercicio_id,status);
create index if not exists ix_fin10_suprimento_prazo on sigov.financeiro_suprimento(tenant_id,entidade_id,exercicio_id,servidor_id,status,prazo_prestacao);

-- RBAC é persistido e o runtime continua fail-closed. Nenhum dado financeiro operacional é semeado.
do $$ declare p text; begin
 foreach p in array array['FINANCEIRO_DASHBOARD_VIEW','FINANCEIRO_ORCAMENTO_VIEW','FINANCEIRO_ORCAMENTO_MANAGE','FINANCEIRO_DOTACAO_VIEW','FINANCEIRO_DOTACAO_MANAGE','FINANCEIRO_EMPENHO_VIEW','FINANCEIRO_EMPENHO_MANAGE','FINANCEIRO_LIQUIDACAO_VIEW','FINANCEIRO_LIQUIDACAO_MANAGE','FINANCEIRO_ORDEM_PAGAMENTO_VIEW','FINANCEIRO_ORDEM_PAGAMENTO_MANAGE','TESOURARIA_CONTA_VIEW','TESOURARIA_CONTA_MANAGE','TESOURARIA_PAGAMENTO_VIEW','TESOURARIA_PAGAMENTO_MANAGE','TESOURARIA_CONCILIACAO_VIEW','TESOURARIA_CONCILIACAO_MANAGE','FINANCEIRO_RECEITA_VIEW','FINANCEIRO_RECEITA_MANAGE','FINANCEIRO_RESTOS_PAGAR_VIEW','FINANCEIRO_RESTOS_PAGAR_MANAGE','FINANCEIRO_SUPRIMENTO_VIEW','FINANCEIRO_SUPRIMENTO_MANAGE','FINANCEIRO_RELATORIO_EXPORT','FINANCEIRO_AUDITORIA_VIEW'] loop
  insert into sigov.permissao(modulo,chave,recurso,acao,descricao,ativo,is_deleted) select 'financeiro',p,'financeiro.'||lower(p),case when p like '%_VIEW' then 'visualizar' else 'gerenciar' end,'Permissão FUNC10 Financeiro/SIAFIC/Tesouraria',true,false where not exists(select 1 from sigov.permissao x where x.chave=p);
 end loop;
end $$;
